import{_ as r,c as a,ag as e,o}from"./chunks/framework.BxW8Wou5.js";const c=JSON.parse('{"title":"1、设计模式概述","description":"","frontmatter":{},"headers":[],"relativePath":"ruankao/软件设计师/第8章 - 设计模式/1.概述.md","filePath":"ruankao/软件设计师/第8章 - 设计模式/1.概述.md","lastUpdated":1762439185000}'),d={name:"ruankao/软件设计师/第8章 - 设计模式/1.概述.md"};function i(n,t,l,b,s,h){return o(),a("div",null,t[0]||(t[0]=[e('<h1 id="_1、设计模式概述" tabindex="-1">1、设计模式概述 <a class="header-anchor" href="#_1、设计模式概述" aria-label="Permalink to &quot;1、设计模式概述&quot;">​</a></h1><h2 id="要素" tabindex="-1">要素 <a class="header-anchor" href="#要素" aria-label="Permalink to &quot;要素&quot;">​</a></h2><ul><li>每一个模式描述了一个在我们周围不断重复发生的问题，以及该问题的解决方案的核心</li><li>采用设计模式<strong>以复用成功的设计</strong></li></ul><h2 id="分类" tabindex="-1">分类 <a class="header-anchor" href="#分类" aria-label="Permalink to &quot;分类&quot;">​</a></h2><p>按照设计模式的目的可以分为三大类：创建型（与对象的创建有关）、结构型（处理类或对象的组合）、行为型（对类或对象怎样交互和怎样分配职责进行描述） 每种模式也分为类模式和对象模式</p><table tabindex="0"><thead><tr><th></th><th>创建型</th><th>结构型</th><th>行为型</th></tr></thead><tbody><tr><td>类</td><td>工厂方法模式（Factory Method）</td><td>适配器模式（Adapter）（类）</td><td>解释器模式（Interpreter）<br>模板方法模式 （Template Method）</td></tr><tr><td>对象</td><td>抽象工厂模式（Abstract Factory）<br>生成器模式（Builder）<br>原型模式（Prototype）<br>单例模式（Singleton）</td><td>适配器模式（Adapter）（对象）<br>桥接模式（Bridge）<br>组合模式（Composite）<br>装饰模式（Decorator）<br>外观模式（Facade）<br>享元模式（Flyweight）<br>代理模式（Proxy）</td><td>责任链模式（Chain of Responsibility）<br>命令模式（Command）<br>迭代器模式（Iterator）<br>终结者模式（Mediator）<br>备忘录模式（Memento）<br>观察者模式（Observer）<br>状态模式（State）<br>策略模式（Strategy）<br>访问者模式（Visitor）</td></tr></tbody></table>',6)]))}const p=r(d,[["render",i]]);export{c as __pageData,p as default};
